        escapes = {'*': r'\*', '+': r'\+', '?': r'\?', '^': r'\^', '$': r'\$', '.': r'\.', '|': r'\|', '(': r'\(', ')': r'\)', '[': r'\[', ']': r'\]', '{': r'\{', '}': r'\}', '\\': r'\\', '\n': r'\n', '\r': r'\r', '\t': r'\t'}
        o = ""
        for c in self.val:
            if c in escapes: o += escapes[c]
            else: o += c
        return o
    def needs_wrap(self): return len(self.val) > 1

class Symbol(ASTNode):
    def __init__(self, name): self.name = name
    def stringify(self):
        m = {'char': '.', 'space': ' ', 'whitespace': r'\s', 'digit': r'\d', 'word': r'\w', 'newline': r'\n', 'tab': r'\t', 'return': r'\r', 'boundary': r'\b', 'null': r'\0', 'backspace': r'[\b]', 'start': '^', 'end': '$', 'alphabetic': '[a-zA-Z]', 'alphanumeric': '[a-zA-Z0-9]', 'vertical': r'\v', 'feed': r'\f'}
