    def __init__(self, amt, atom): self.amt, self.atom = amt, atom
    def stringify(self):
        base = self.atom.stringify()
        if self.atom.needs_wrap(): base = f"(?:{base})"
        return f"{base}{self.amt}"
    def needs_wrap(self): return False

